using Monergy.Platform;
using Monergy.Services.JobManagement.Application;
namespace Monergy.Services.JobManagement.Infrastructure;

public sealed partial class InMemoryJobRepository:IJobAdministrationRepository
{
 private readonly Dictionary<string,AdminJobReceipt> adminReceipts=new(StringComparer.Ordinal);
 private DurableJobRecord AdminRequired(AdminJobScope scope,string jobId)=>jobs.TryGetValue(jobId,out var job)&&scope.Owns(job)?job:throw new TenantBoundaryException("PROCESSING_JOB_NOT_FOUND",404);
 public Task<AdminJobPage> ListAdminAsync(AdminJobScope scope,AdminJobQuery query,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();JobAdministration.Query(query);lock(sync){var all=jobs.Values.Where(scope.Owns).Where(x=>query.DocumentVersionId is null||x.JobName=="document-processing"&&x.PayloadReference==query.DocumentVersionId).Where(x=>query.CustomerId is null||x.CustomerId==query.CustomerId).ToArray();var filtered=all.Where(x=>(query.CustomerId is null||x.CustomerId==query.CustomerId)&&(query.State=="all"||JobAdministration.State(x)==query.State)&&x.JobId.Contains(query.Search,StringComparison.OrdinalIgnoreCase)).OrderByDescending(x=>x.RequestedAt).ThenByDescending(x=>x.JobId,StringComparer.Ordinal).ToArray();IEnumerable<DurableJobRecord> eligible=filtered;if(query.After is not null){var cursor=AdminRequired(scope,query.After);if(query.CustomerId is not null&&cursor.CustomerId!=query.CustomerId||query.DocumentVersionId is not null&&(cursor.JobName!="document-processing"||cursor.PayloadReference!=query.DocumentVersionId))throw new TenantBoundaryException("PROCESSING_JOB_NOT_FOUND",404);eligible=filtered.Where(x=>x.RequestedAt<cursor.RequestedAt||x.RequestedAt==cursor.RequestedAt&&StringComparer.Ordinal.Compare(x.JobId,cursor.JobId)<0);}var page=eligible.Take(51).ToArray();return Task.FromResult(new AdminJobPage(scope.TenantId,page.Take(50).Select(x=>JobAdministration.Summary(scope,x)).ToArray(),page.Length>50?page[49].JobId:null,filtered.Length,JobAdministration.Counts(all)));}}
 public Task<AdminJobSummary?> ReadAdminAsync(AdminJobScope scope,string jobId,CancellationToken ct){ct.ThrowIfCancellationRequested();lock(sync){var row=jobs.GetValueOrDefault(jobId);return Task.FromResult(row is not null&&scope.Owns(row)?JobAdministration.Summary(scope,row):null);}}
 public Task<AdminJobAttempts> AttemptsAdminAsync(AdminJobScope scope,string jobId,int? before,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();lock(sync){AdminRequired(scope,jobId);var page=attempts.Values.Where(x=>x.JobId==jobId&&(before is null||x.Attempt<before)).OrderByDescending(x=>x.Attempt).Take(51).ToArray();return Task.FromResult(new AdminJobAttempts(scope.TenantId,jobId,page.Take(50).Select(x=>new AdminJobAttempt(x.Attempt,x.StartedAt,x.EndedAt,JobAdministration.Safe(x.Outcome),JobAdministration.Safe(x.FailureCode),x.Retryable)).ToArray(),page.Length>50?page[49].Attempt:null));}}
 public Task<AdminJobReceipt> ChangeAdminAsync(AdminJobScope scope,string actor,string jobId,AdminJobChange change,DateTimeOffset now,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();JobAdministration.Change(change);now=JobAdministration.Time(now);lock(sync){var job=AdminRequired(scope,jobId);if(adminReceipts.TryGetValue(change.OperationId,out var prior)){JobAdministration.Match(prior,scope,actor,jobId,change);return Task.FromResult(prior);}if(change.Action=="retry"&&!scope.AllowsRetry(job))throw new TenantBoundaryException("PROCESSING_RETRY_UNAVAILABLE",409);var after=JobAdministration.Apply(job,change,now);var receipt=new AdminJobReceipt(scope.TenantId,jobId,change.OperationId,change.Action,change.Reason,actor,now,JobAdministration.Summary(scope,job),JobAdministration.Summary(scope,after));jobs[jobId]=after;adminReceipts.Add(change.OperationId,receipt);return Task.FromResult(receipt);}}
 public Task<AdminJobReceipt?> ReceiptAdminAsync(AdminJobScope scope,string jobId,string operation,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();lock(sync){AdminRequired(scope,jobId);var row=adminReceipts.GetValueOrDefault(operation);return Task.FromResult(row?.TenantId==scope.TenantId&&row.JobId==jobId?row:null);}}
 public Task<AdminJobHistory> HistoryAdminAsync(AdminJobScope scope,string jobId,string? before,CancellationToken ct)
 {ct.ThrowIfCancellationRequested();lock(sync){AdminRequired(scope,jobId);var all=adminReceipts.Values.Where(x=>x.TenantId==scope.TenantId&&x.JobId==jobId).OrderByDescending(x=>x.RecordedAt).ThenByDescending(x=>x.OperationId,StringComparer.Ordinal).ToArray();var offset=0;if(before is not null){offset=Array.FindIndex(all,x=>x.OperationId==before)+1;if(offset==0)throw new TenantBoundaryException("PROCESSING_HISTORY_CURSOR_INVALID",400);}var page=all.Skip(offset).Take(51).ToArray();return Task.FromResult(new AdminJobHistory(scope.TenantId,jobId,page.Take(50).ToArray(),page.Length>50?page[49].OperationId:null));}}
}
